CREATE FUNCTION pg_temp.improved(q text, idx text) RETURNS TABLE(used_in_plan boolean, cheaper_than_without boolean) AS $$ DECLARE p text; c1 numeric; c2 numeric; BEGIN IF to_regclass(idx) IS NULL THEN RETURN QUERY SELECT false, false; RETURN; END IF; p := pg_temp.plan_of(q); c1 := substring(p from 'cost=[0-9.]+\.\.([0-9.]+)')::numeric; EXECUTE 'DROP INDEX ' || idx; c2 := substring(pg_temp.plan_of(q) from 'cost=[0-9.]+\.\.([0-9.]+)')::numeric; RETURN QUERY SELECT p LIKE '%' || idx || '%', c1 < c2; END $$ LANGUAGE plpgsql;
