-- обе сессии
BEGIN;
SELECT rating FROM pizzeria WHERE name = 'Pizza Hut';
-- Session #1
UPDATE pizzeria SET rating = ______ WHERE name = 'Pizza Hut';
-- Session #2 (ждёт)
UPDATE pizzeria SET rating = ______ WHERE name = 'Pizza Hut';
-- Session #1
COMMIT;
-- Session #2
COMMIT;
```

