DROP FUNCTION ______();          -- три раза
TRUNCATE person_audit;

CREATE FUNCTION fnc_trg_person_audit() RETURNS trigger AS $$
BEGIN
    IF (TG_OP = '______') THEN ... ('I', NEW...)
    ELSIF (TG_OP = 'UPDATE') THEN ... ('U', OLD...)
    ELSIF (TG_OP = 'DELETE') THEN ... ('D', OLD...)
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;
```

